-- 012_tasks_source_key.sql — make the Follow-up Queue syncable.
--
-- A task generated by the engine (Posting Workbench item, Pre-approval Review
-- encounter) carries a stable source_key so a nightly sync UPSERTS it instead of
-- duplicating it: the engine refreshes title / detail / dollars / priority, while
-- a human's assignee, status and due date survive. NULL keys (hand-made tasks)
-- never conflict. Adds the 'review' source. Re-runnable.
-- Apply to a live database on its own:  npm run db:migrate -- --only=012

alter table public.tasks add column if not exists source_key text;
create unique index if not exists tasks_source_key_idx on public.tasks(tenant_id, source_key);

do $$
declare c record;
begin
  for c in
    select conname
    from pg_constraint
    where conrelid = 'public.tasks'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) like '%source%'
      and pg_get_constraintdef(oid) not like '%status%'
      and pg_get_constraintdef(oid) not like '%priority%'
  loop
    execute format('alter table public.tasks drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.tasks
  add constraint tasks_source_check
  check (source in ('denial', 'follow_up', 'balance', 'review'));
